import("gn/codec.gni")
import("gn/pathops.gni")
import("gn/rust.gni")
import("gn/shared_sources.gni")
import("gn/skia.gni")
import("gn/toolchain/wasm.gni")

if (defined(skia_settings)) {
  import(skia_settings)
